for label in ['hw-nx-base-a','hw-hevc-a','hw-nx-base-b','hw-hevc8-a','hw-hevc8-b']:
 src=live/(label+'-client.log');row=json.loads(subprocess.check_output(['python3',str(r/'nx-scratch/sha2-transport/analyze_warm.py'),str(src)],text=True));rows.append(row)
